public class JavaCommandBuilderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.util.Map<String, String> props(String k1, String v1, String k2, String v2) {
        java.util.Map<String, String> map = new java.util.LinkedHashMap<>();
        map.put(k1, v1);
        map.put(k2, v2);
        return map;
    }

    public static void main(String[] args) {
        java.util.Map<String, String> props = new java.util.LinkedHashMap<>();
        props.put("user.language", "en");
        props.put("file.encoding", "UTF-8");

        check("full command", "[java, -cp, build, -Dfile.encoding=UTF-8, -Duser.language=en, Main, 7]",
                JavaCommandBuilder.buildRunCommand("build", props, "Main", java.util.Arrays.asList("7")).toString());
        check("no classpath", "[java, Main]",
                JavaCommandBuilder.buildRunCommand("   ", null, "Main", null).toString());
        check("null classpath", "[java, Demo, a, b]",
                JavaCommandBuilder.buildRunCommand(null, null, "Demo", java.util.Arrays.asList("a", "b")).toString());
        check("properties sorted by key", "[java, -Da=1, -Db=2, Main]",
                JavaCommandBuilder.buildRunCommand(null, props("b", "2", "a", "1"), "Main", null).toString());

        String thrown = "none";
        try {
            JavaCommandBuilder.buildRunCommand("build", null, "  ", null);
        } catch (IllegalArgumentException e) {
            thrown = "IllegalArgumentException";
        } catch (RuntimeException e) {
            thrown = e.getClass().getSimpleName();
        }
        check("blank main class rejected", "IllegalArgumentException", thrown);

        check("command line joins tokens", "java -cp build Main",
                JavaCommandBuilder.asCommandLine(java.util.Arrays.asList("java", "-cp", "build", "Main")));
        check("command line quotes spaces", "java -cp \"my build\" Main",
                JavaCommandBuilder.asCommandLine(java.util.Arrays.asList("java", "-cp", "my build", "Main")));
        check("command line of empty list", "",
                JavaCommandBuilder.asCommandLine(new java.util.ArrayList<String>()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

