public class JavaCommandBuilder {

    public static java.util.List<String> buildRunCommand(String classpath,
                                                         java.util.Map<String, String> systemProperties,
                                                         String mainClass,
                                                         java.util.List<String> programArgs) {
        if (mainClass == null || mainClass.trim().isEmpty()) {
            throw new IllegalArgumentException("mainClass is required");
        }
        java.util.List<String> tokens = new java.util.ArrayList<>();
        tokens.add("java");
        if (classpath != null && !classpath.trim().isEmpty()) {
            tokens.add("-cp");
            tokens.add(classpath.trim());
        }
        if (systemProperties != null) {
            java.util.Map<String, String> sorted = new java.util.TreeMap<>(systemProperties);
            for (java.util.Map.Entry<String, String> entry : sorted.entrySet()) {
                tokens.add("-D" + entry.getKey() + "=" + entry.getValue());
            }
        }
        tokens.add(mainClass.trim());
        if (programArgs != null) {
            tokens.addAll(programArgs);
        }
        return tokens;
    }

    public static String asCommandLine(java.util.List<String> tokens) {
        if (tokens == null) {
            return "";
        }
        StringBuilder line = new StringBuilder();
        for (String token : tokens) {
            if (line.length() > 0) {
                line.append(' ');
            }
            if (token.contains(" ")) {
                line.append('"').append(token).append('"');
            } else {
                line.append(token);
            }
        }
        return line.toString();
    }
}
